window.kbPageData["views/entry/k-b4942ae6eae340e8"] = {"key":"entry/k-b4942ae6eae340e8","state":{"route":"entry/k-b4942ae6eae340e8"},"node":{"id":"k-b4942ae6eae340e8","mode":"k","title":"碳排放双控","type":"制度与规则","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":["碳排放总量和强度双控制度"],"qs":["国考 2025 副省级 行测#15","国考 2025 行政执法 行测#15"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":1,"reviewSet":"多题条目","independentCount":1,"tags":{"专题":["ecology"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["生态环境"],"来源主题":["生态环境与能源"],"资料类别":["非时政"]},"directorySummary":"碳排放双控是同时管理碳排放总量和强度的制度。总量衡量一定范围内的排放规模，强度通常以单位国内生产总值的碳排放量衡量。","review":{"title":"碳排放双控","type":"制度与规则","definition":"碳排放双控是同时管理碳排放总量和强度的制度。总量衡量一定范围内的排放规模，强度通常以单位国内生产总值的碳排放量衡量。","explanation":"2024年《中共中央关于进一步全面深化改革、推进中国式现代化的决定》第（49）项提出，建立能耗双控向碳排放双控全面转型新机制。随着转型推进，双控的对象由能源消费转向碳排放。","basis":"据关联原题及所列出处编释。","references":[{"source":"reform","location":"健全绿色低碳发展机制"}],"domain":"生态环境","examFocus":{"国考 2025 副省级 行测#15":"对照党的二十届三中全会《决定》，核对绿色低碳措施的对象及双控制度的转型方向。"}},"aspects":[{"title":"能耗双控向碳排放双控转型","uses":[{"unit":"Q1","role":"直接考查","use":"题干要求选出健全绿色低碳发展机制中不恰当的举措。B项将《决定》规定的转型方向写反。","evidence":"建立碳排放双控向能耗双控全面转型新机制","qids":["国考 2025 副省级 行测#15","国考 2025 行政执法 行测#15"]}]}],"sources":[{"id":"af6fa182a8393e20","label":"碳排放总量和强度双控制度","topic":"生态环境与能源","category":"非时政","text":"7.碳排放总量和强度双控制度\n“十五五”时期，实施以强度控制为主、总量控制为辅的碳排放双控制度，建立碳达峰\n碳中和综合评价考核制度，加强重点领域和行业碳排放核算能力，健全重点用能和碳排放单\n位管理制度，开展固定资产投资项目碳排放评价，构建符合中国国情的产品碳足迹管理体系\n和产品碳标识认证制度，确保如期实现碳达峰目标。\n碳达峰后，实施以总量控制为主、强度控制为辅的碳排放双控制度，建立碳中和目标评\n价考核制度，进一步强化对各地区及重点领域、行业、企业的碳排放管控要求，健全产品碳\n足迹管理体系，推行产品碳标识认证制度，推动碳排放总量稳中有降。\n——《加快构建碳排放双控制度体系工作方案》","source":{"doc":"6cbfb01fe723bba64b75","first":47,"last":47,"page":47,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"国考 2025 副省级 行测#15":{"paper":"国考 2025 副省级 行测","n":15,"mod":"政治理论","src":["ffe12c35a46d4df574ec.pdf",3],"asrc":["ff0b352b44d417525086.pdf",5],"card":"f9a51ced9d40a9a2b1529273","links":[{"id":"k-b4942ae6eae340e8","role":"直接考查","why":"题目考查从能耗双控转向碳排放双控的政策方向。"}]},"国考 2025 行政执法 行测#15":{"paper":"国考 2025 行政执法 行测","n":15,"mod":"政治理论","src":["d8efe4e19862104d89c8.pdf",3],"asrc":["e2c4b1970d2b49eac0fd.pdf",5],"card":"1e3abbb0852378a728f52b8f","links":[{"id":"k-b4942ae6eae340e8","role":"直接考查","why":"政策规定由能耗双控全面转向碳排放双控，转型方向决定举措是否恰当。"}]}},"terms":{},"references":{"reform":{"name":"《中共中央关于进一步全面深化改革、推进中国式现代化的决定》（2024年）","url":"https://www.miit.gov.cn/xwdt/szyw/art/2024/art_7ba61714bf074c29b0135ddfe4c1e7cd.html"}},"topics":[{"slug":"ecology","title":"生态保护与绿色转型"}],"units":{"k-b4942ae6eae340e8":[["国考 2025 副省级 行测#15","国考 2025 行政执法 行测#15"]]}};
